SELECT u.id AS use_id, w.state, w.finished_at
  FROM tools.uses u
  JOIN agents.work_items w ON w.wire_tool_use_id = u.wire_tool_use_id
 WHERE u.id = ANY(ARRAY[999876,999874,999872,999869,999868,999866,999864,999862,999859,999857,999827,999823,999815,999810,999808,999806,999804,999802,999800,999798,999796,999792,999791,999790,999788,999782,999778,999769,999766,999764,999761,999757,999748,999743,999723,999721,999714,999692,999688,999686]::bigint[])
